-- --------------------------------------------------------
-- ตาราง `employers`
-- --------------------------------------------------------
CREATE TABLE `employers` (
  `id` int NOT NULL AUTO_INCREMENT,
  `email` varchar(255) NOT NULL,
  `password_hash` varchar(255) NOT NULL,
  `company_name` varchar(255) NOT NULL,
  `address` text DEFAULT NULL,
  `industry` varchar(100) DEFAULT NULL,
  `logo_url` varchar(500) DEFAULT NULL,
  `is_approved` tinyint(1) DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`) /*T![clustered_index] CLUSTERED */,
  KEY `ix_employers_id` (`id`),
  UNIQUE KEY `ix_employers_email` (`email`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

-- --------------------------------------------------------
-- ตาราง `job_postings`
-- --------------------------------------------------------
CREATE TABLE `job_postings` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL,
  `company_id` int DEFAULT NULL,
  `title` varchar(255) NOT NULL,
  `department` varchar(100) DEFAULT NULL,
  `description` text DEFAULT NULL,
  `daily_allowance` int DEFAULT NULL,
  `location` varchar(255) DEFAULT NULL,
  `is_active` tinyint(1) DEFAULT NULL,
  `status` varchar(20) DEFAULT NULL,
  `rejection_reason` text DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`) /*T![clustered_index] CLUSTERED */,
  KEY `fk_1` (`user_id`),
  KEY `fk_2` (`company_id`),
  KEY `ix_job_postings_id` (`id`),
  CONSTRAINT `fk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_2` FOREIGN KEY (`company_id`) REFERENCES `companies` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

-- --------------------------------------------------------
-- ตาราง `reviews`
-- --------------------------------------------------------
CREATE TABLE `reviews` (
  `id` int NOT NULL AUTO_INCREMENT,
  `company_id` int NOT NULL,
  `user_id` int NOT NULL,
  `gender` enum('male','female','prefer_not') NOT NULL,
  `period_start` date NOT NULL,
  `period_end` date NOT NULL,
  `department` varchar(100) NOT NULL,
  `daily_allowance` int DEFAULT NULL,
  `work_start_time` varchar(50) DEFAULT NULL,
  `work_end_time` varchar(50) DEFAULT NULL,
  `score_overall` float NOT NULL,
  `score_work` float DEFAULT NULL,
  `score_env` float DEFAULT NULL,
  `score_mentor` float DEFAULT NULL,
  `score_welfare` float DEFAULT NULL,
  `text_work` text NOT NULL,
  `text_pros` text DEFAULT NULL,
  `text_cons` text DEFAULT NULL,
  `text_advice` text DEFAULT NULL,
  `status` enum('pending','approved','rejected') DEFAULT NULL,
  `rejection_reason` text DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`) /*T![clustered_index] CLUSTERED */,
  KEY `fk_1` (`company_id`),
  KEY `fk_2` (`user_id`),
  KEY `ix_reviews_id` (`id`),
  CONSTRAINT `fk_1` FOREIGN KEY (`company_id`) REFERENCES `companies` (`id`),
  CONSTRAINT `fk_2` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin AUTO_INCREMENT=150003;

