-- --------------------------------------------------------
-- ตาราง `reports`
-- --------------------------------------------------------
CREATE TABLE `reports` (
  `id` int NOT NULL AUTO_INCREMENT,
  `reporter_id` int NOT NULL,
  `post_id` int DEFAULT NULL,
  `review_id` int DEFAULT NULL,
  `comment_id` int DEFAULT NULL,
  `job_id` int DEFAULT NULL,
  `company_id` int DEFAULT NULL,
  `reason` text NOT NULL,
  `status` varchar(20) DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`) /*T![clustered_index] CLUSTERED */,
  KEY `fk_1` (`reporter_id`),
  KEY `fk_2` (`post_id`),
  KEY `fk_3` (`review_id`),
  KEY `fk_4` (`comment_id`),
  KEY `fk_5` (`job_id`),
  KEY `fk_6` (`company_id`),
  KEY `ix_reports_id` (`id`),
  CONSTRAINT `fk_1` FOREIGN KEY (`reporter_id`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_2` FOREIGN KEY (`post_id`) REFERENCES `community_posts` (`id`),
  CONSTRAINT `fk_3` FOREIGN KEY (`review_id`) REFERENCES `reviews` (`id`),
  CONSTRAINT `fk_4` FOREIGN KEY (`comment_id`) REFERENCES `community_comments` (`id`),
  CONSTRAINT `fk_5` FOREIGN KEY (`job_id`) REFERENCES `job_postings` (`id`),
  CONSTRAINT `fk_6` FOREIGN KEY (`company_id`) REFERENCES `companies` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin AUTO_INCREMENT=30002;

-- ข้อมูลตาราง `reports` (1 แถว)
INSERT INTO `reports` (`id`, `reporter_id`, `post_id`, `review_id`, `comment_id`, `job_id`, `company_id`, `reason`, `status`, `created_at`) VALUES
  (1, 1, NULL, 60003, NULL, NULL, NULL, 'ข้อมูลเท็จ / หลอกลวง', 'dismissed', '2026-08-25 16:39:56');

-- --------------------------------------------------------
-- ตาราง `upgrade_requests`
-- --------------------------------------------------------
CREATE TABLE `upgrade_requests` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL,
  `student_id` varchar(50) NOT NULL,
  `department` varchar(100) DEFAULT NULL,
  `phone` varchar(50) DEFAULT NULL,
  `reason` text DEFAULT NULL,
  `status` enum('pending','approved','rejected') DEFAULT NULL,
  `rejection_reason` text DEFAULT NULL,
  `card_image_url` longtext DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`) /*T![clustered_index] CLUSTERED */,
  KEY `fk_1` (`user_id`),
  KEY `ix_upgrade_requests_id` (`id`),
  CONSTRAINT `fk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin AUTO_INCREMENT=30002;

-- ข้อมูลตาราง `upgrade_requests` (2 แถว)
